// Derecho Engine - the scene: entities, transforms and JSON persistence.
//
// This is the first piece of the engine's data model. Everything that is not
// the procedural world (props, markers, lights, and later characters and
// scripted objects) lives here, is editable in the debug panel, and round-trips
// through a plain JSON scene file.
#pragma once

#include "math/Math.h"

#include <string>
#include <utility>
#include <vector>

namespace derecho::scene {

using EntityId = uint32_t;
constexpr EntityId kInvalidEntity = 0;

// Built-in primitive shapes. Meshes are generated by the engine, so a scene can
// exist without any external asset files yet.
enum class Primitive { Box = 0, Sphere, Cylinder, Cone, Count };

const char* PrimitiveName(Primitive primitive);
bool ParsePrimitive(const std::string& text, Primitive& out);

struct Entity {
    EntityId id = kInvalidEntity;
    bool alive = false;
    std::string name;

    vec3 position{0.0f, 0.0f, 0.0f};
    vec3 rotation{0.0f, 0.0f, 0.0f};   // degrees, applied Z then Y then X
    vec3 scale{1.0f, 1.0f, 1.0f};

    Primitive primitive = Primitive::Box;
    vec3 color{0.72f, 0.74f, 0.78f};
    bool castShadow = true;
    bool visible = true;

    // Optional imported assets. When `mesh` names a model in the asset library
    // it replaces the primitive; `texture` names an albedo map ("" = flat tint).
    std::string mesh;
    std::string texture;
    EntityId parent = kInvalidEntity;

    // Behaviour attached to this entity ("" = none) plus its tunable floats.
    // Both are plain data so the scene file stays self-describing.
    std::string script;
    std::vector<std::pair<std::string, float>> scriptParams;

    float Param(const char* name, float fallback) const;
    void SetParam(const std::string& name, float value);

    mat4 LocalMatrix() const;
};

class Scene {
public:
    void Clear();

    EntityId Create(const std::string& name, Primitive primitive, const vec3& position);
    bool Destroy(EntityId id);

    Entity* Find(EntityId id);
    const Entity* Find(EntityId id) const;

    // Dense list including dead slots; check `alive` before using an entry.
    const std::vector<Entity>& Entities() const { return m_entities; }
    std::vector<Entity>& Entities() { return m_entities; }

    size_t AliveCount() const;

    // Resolves the parent chain. Root entities return their local matrix.
    mat4 WorldMatrix(const Entity& entity) const;

    // Assigns a unique name such as "Box 3".
    std::string UniqueName(const std::string& base) const;

    const std::string& Path() const { return m_path; }
    void SetPath(std::string path) { m_path = std::move(path); }

    bool Save(const std::string& path, std::string& error) const;
    bool Load(const std::string& path, std::string& error);

private:
    std::vector<Entity> m_entities;
    EntityId m_nextId = 1;
    std::string m_path = "scene.json";
};

} // namespace derecho::scene
